type Size = NonNullable<LogoProps['size']>;

const HEIGHT: Record<Size, string> = {
  sm: 'h-7',
  md: 'h-12',
  lg: 'h-20',
  xl: 'h-28 md:h-36',
};

/** Chunky darker-blue under-edge + soft brand glow so the white mark pops on the navy background. */
const GLOW: Record<Size, string> = {
  sm: 'drop-shadow(0 1px 0 rgba(28,82,144,0.9)) drop-shadow(0 0 6px rgba(58,140,214,0.55))',
  md: 'drop-shadow(0 2px 0 rgba(28,82,144,0.9)) drop-shadow(0 0 10px rgba(58,140,214,0.6))',
  lg: 'drop-shadow(0 3px 0 rgba(28,82,144,0.9)) drop-shadow(0 0 16px rgba(58,140,214,0.6))',
  xl: 'drop-shadow(0 4px 0 rgba(28,82,144,0.9)) drop-shadow(0 0 24px rgba(58,140,214,0.65))',
};

const spring = (delay: number, stiffness = 520, damping = 22): Transition => ({
  type: 'spring',
  stiffness,
  damping,
  delay,
});

const letterV: Variants = {
  hidden: { opacity: 0, y: 46 },
  show: (i: number) => ({ opacity: 1, y: 0, transition: spring(0.05 + i * 0.045) }),
};

const bigZV: Variants = {
  hidden: { opacity: 0, y: 30, scale: 0.4 },
  show: { opacity: 1, y: 0, scale: 1, transition: spring(0.45, 420, 14) },
};

// framer-motion 11.11's `Target` type collapses `pathLength` to `never` (upstream typing quirk),
// although animating it on motion.path is the documented draw-on technique — hence the cast.
const drawV = (delay: number, duration: number) =>
  ({
    hidden: { pathLength: 0 },
    show: { pathLength: 1, transition: { delay, duration, ease: [0.65, 0, 0.35, 1] } },
  }) as unknown as Variants;
const swooshV = drawV(0.4, 0.75);
const hookV = drawV(0.7, 0.45);

const houseV: Variants = {
  hidden: { opacity: 0, y: -90 },
  show: {
    opacity: 1,
    y: 0,
    transition: { y: spring(0.85, 620, 12), opacity: { delay: 0.85, duration: 0.12 } },
  },
};

const dieV: Variants = {
  hidden: { opacity: 0, x: 60, y: -40, rotate: 240, scale: 0.4 },
  show: {
    opacity: 1,
    x: 0,
    y: 0,
    rotate: 0,
    scale: 1,
    transition: { ...spring(1.05, 240, 13), opacity: { delay: 1.05, duration: 0.15 } },
  },
};

export function Logo({ size = 'md', className, animated = false }: LogoProps) {
  const reduceMotion = useReducedMotion();
  const play = animated && !reduceMotion;
  const uid = `mz${useId().replace(/[^a-zA-Z0-9_-]/g, '')}`;

  return (
    <motion.svg
      viewBox={`0 0 ${VIEW_W} ${VIEW_H}`}
      role="img"
      aria-label="MonopoliZ"
      focusable="false"
      className={clsx('block w-auto shrink-0 select-none', HEIGHT[size], className)}
      style={{ aspectRatio: `${VIEW_W} / ${VIEW_H}`, overflow: 'visible', filter: GLOW[size] }}
      initial={play ? 'hidden' : false}
      animate="show"
      fill="#fff"
    >
      {play && (
        <defs>
          <mask id={`${uid}-swoosh`}>
            <motion.path
              d={SWOOSH_LINE}
              fill="none"
              stroke="#fff"
              strokeWidth={26}
              strokeLinecap="round"
              strokeLinejoin="round"
              variants={swooshV}
            />
          </mask>
          <mask id={`${uid}-hook`}>
            <motion.path
              d={HOOK_LINE}
              fill="none"
              stroke="#fff"
              strokeWidth={26}
              strokeLinecap="round"
              strokeLinejoin="round"
              variants={hookV}
            />
          </mask>
        </defs>
      )}

      <path d={SWOOSH} mask={play ? `url(#${uid}-swoosh)` : undefined} />
      <path d={HOOK} mask={play ? `url(#${uid}-hook)` : undefined} />

      {LETTERS.slice(0, -1).map((d, i) => (
        <motion.path key={i} d={d} custom={i} variants={letterV} />
      ))}
      <motion.path d={LETTERS[LETTERS.length - 1]} variants={bigZV} style={{ originY: 1 }} />

      <motion.path d={HOUSE} variants={houseV} style={{ originY: 1 }} />
      <motion.g variants={dieV}>
        {/* invisible box keeps the rotation centred on the die */}
        <rect x={DIE_BOX.x} y={DIE_BOX.y} width={DIE_BOX.w} height={DIE_BOX.h} fill="none" />
        <path d={DIE} />
      </motion.g>
    </motion.svg>
  );
}
